  defmodule UntilCancelled do
    use JoobQ.Worker, queue: "mail", job_type: "until_cancelled"

    @impl JoobQ.Worker
    def perform(job) do
      if JoobQ.Job.heartbeat(job) do
        {:error, JoobQ.NonRetryable.exception("cancelled")}
      else
        Process.sleep(50)
        perform(job)
      end
    end
