  test "a renewal that hangs does not hold back the next round" do
    bypass = Bypass.open()
    test_pid = self()
    polls = TestGateway.counter()
    renewals = TestGateway.counter()

    task = %{
      "lease_token" => "lease-2",
      "kind" => "job",
      "id" => "j2",
      "name" => "until_cancelled"
    }

    TestGateway.stub(bypass, "POST", "/api/v1/sdk/tasks/poll", fn conn ->
      answer = if TestGateway.tick(polls) == 0, do: [task], else: []
      if answer == [], do: Process.sleep(100)
      Plug.Conn.resp(conn, 200, Jason.encode!(%{tasks: answer}))
    end)

    TestGateway.stub(bypass, "POST", "/api/v1/sdk/tasks/heartbeat", fn conn ->
      send(test_pid, {:renewal, System.monotonic_time(:millisecond)})

      if TestGateway.tick(renewals) == 0 do
        Process.sleep(1_600)
        send(test_pid, :slow_answered)
      end

      lease = %{lease_token: "lease-2", cancel_requested: true, lease_until_ms: 0, error: nil}
      Plug.Conn.resp(conn, 200, Jason.encode!(%{leases: [lease]}))
    end)

    TestGateway.stub(bypass, "POST", "/api/v1/sdk/tasks/ack", fn conn ->
      Plug.Conn.resp(conn, 200, ~s({"results":[]}))
    end)

    TestGateway.start_worker(bypass,
      workers: [UntilCancelled],
      lease_ttl_ms: 3_000,
      except: [:poll, :heartbeat]
    )

    # Rounds are 1 s apart; the first call hangs 1.6 s.
    assert_receive {:renewal, first}, 3_000
    assert_receive {:renewal, second}, 2_000
    assert second - first < 1_450
    assert_receive :slow_answered, 2_500
  end

